"sitelinks":61,"slice":"sports"},{"k":"activity:luge","kind":"activity","l":"luge","labels":[["luge","luge","en","preferred"],["artificial luge olympic luge","artificial luge olympic luge","en","alternate"],["luge on natural track","luge on natural track","en","alternate"],["luge on artificial track","luge on artificial track","en","alternate"],["natural track luge","natural track luge","en","alternate"],["リュージュ","リュージュ","ja","alternate"]],"parent":"hub:sports_movement","qid":"Q273285","sitelinks":61,"slice":"sports"},{"k":"activity:orienteering","kind":"activity","l":"orienteering","labels":[["orienteering","orienteering","en","preferred"],["オリエンテーリング","オリエンテーリング","ja","alternate"],["オリエンテーリング選手","オリエンテーリング選手","ja","alternate"],["オリエンテーリング選手一覧","オリエンテーリング選手一覧","ja","alternate"],["오리엔티어링","오리엔티어링","ko","alternate"],["定向运动","定向运动","zh","alternate"]],"parent":"hub:sports_movement","qid":"Q29358","sitelinks":61,"slice":"sports"},{"k":"activity:kabaddi","kind":"activity","l":"kabaddi","labels":[["kabaddi","kabaddi","en","preferred"],["hututu","hututu","en","alternate"],["hududu","hududu","en","alternate"],["sadugudu","sadugudu","en","alternate"],["kaudi","kaudi","en","alternate"],["pakaada","pakaada","en","alternate"]],"parent":"hub:sports_movement","qid":"Q148636","sitelinks":60,"slice":"sports"},{"k":"activity:speed_skating","kind":"activity","l":"speed skating","labels":[["speed skating","speed skating","en","preferred"],["speedskating","speedskating","en","alternate"],["スピードスケート","スピードスケート","ja","alternate"],["スピード・スケート","スピード スケート","ja","alternate"],["스피드스케이팅","스피드스케이팅","ko","alternate"],["롱트랙 스피드 스케이팅","롱트랙 스피드 스케이팅","ko","alternate"]],"parent":"hub:sports_movement","qid":"Q192431","sitelinks":60,"slice":"sports"}]$json$::jsonb);

-- The payload, unpacked into the two shapes the inserts want. A label arrives
-- as `[label, normalized, locale, label_type]`; **`normalized` was computed by
-- `written_ontology.normalize.normalize_text` in Python and is never recomputed
-- here**, because SQL cannot reproduce that fold and `0184` is the migration
-- that had to repair three concepts minted without it.
create temporary table import_concept on commit drop as
select
  entry->>'k'                                        as concept_key,
  entry->>'l'                                        as preferred_label,
  entry->>'kind'                                     as concept_kind,
  entry->>'parent'                                   as parent_key,
  coalesce(
    array(select jsonb_array_elements_text(entry->'parents')),
    array[]::text[])                                 as parent_candidates,
  entry->>'qid'                                      as external_id,
  jsonb_build_object(
    'source', 'wikidata',
    'license', 'CC0-1.0',
    'external_id', entry->>'qid',
    'slice', entry->>'slice',
    'sitelinks', (entry->>'sitelinks')::integer,
    'imported_by', '0199')                           as metadata
from wikidata_payload, jsonb_array_elements(data) as entry;

create temporary table import_label on commit drop as
select
  entry->>'k'    as concept_key,
  entry->>'qid'  as external_id,
  lab->>0        as label,
  lab->>1        as normalized_label,
  lab->>2        as locale,
  lab->>3        as label_type
from wikidata_payload,
     jsonb_array_elements(data) as entry,
     jsonb_array_elements(entry->'labels') as lab;

do $$
declare
  current_version   text;
  next_version      text;
  old_version_id    uuid;
  new_version_id    uuid;
  ambiguous_before  integer;
  ambiguous_after   integer;
  concepts_minted   integer;
  revisions_added   integer;
  labels_added      integer;
  labels_refused    integer;
  edges_added       integer;
  unparented        integer;
  prohibited        integer;
  links_before      integer;
  links_after       integer;
  enqueued          integer;
  probe_block       text;
  refused_topic     text;
begin
  select version, id into current_version, old_version_id
    from ontology.versions where status = 'published';

  -- Counted before anything is added, because the question is never "is
  -- anything ambiguous" — seven labels name two concepts today and every one is
  -- deliberate — but "did this make anything newly ambiguous". `0196`'s first
  -- draft failed on a property the database has never had.
  select count(*) into ambiguous_before
    from (select l.normalized_label
            from ontology.concept_labels l
           where l.ontology_version_id = old_version_id and l.status = 'active'
           group by l.normalized_label having count(distinct l.concept_id) > 1) as already;

  select count(*) into links_before
    from ontology.external_concept_links where ontology_version_id = old_version_id;

  next_version := split_part(current_version, '.', 1) || '.'
               || (split_part(current_version, '.', 2)::integer + 1)::text || '.0';

  insert into ontology.versions (id, version, parent_version_id, status, description)
  values (extensions.gen_random_uuid(), next_version, old_version_id, 'draft',
          'The names Wikidata keeps in the article title rather than the label.');
  select id into new_version_id from ontology.versions where version = next_version;

  -- Copy-forward. **Five tables.** `external_concept_links` is the one the
  -- standard pattern omits, and omitting it is not visible until somebody looks
  -- for provenance that is no longer there.
  insert into ontology.concept_revisions (ontology_version_id, concept_id, preferred_label, concept_kind, definition, sensitivity, inference_policy, status, metadata)
  select new_version_id, r.concept_id, r.preferred_label, r.concept_kind, r.definition, r.sensitivity, r.inference_policy, r.status, r.metadata
    from ontology.concept_revisions r where r.ontology_version_id = old_version_id
  on conflict do nothing;

  insert into ontology.concept_labels (ontology_version_id, concept_id, label, normalized_label, locale, label_type, provenance_type, confidence, status, external_ref)
  select new_version_id, l.concept_id, l.label, l.normalized_label, l.locale, l.label_type, l.provenance_type, l.confidence, l.status, l.external_ref
    from ontology.concept_labels l where l.ontology_version_id = old_version_id
  on conflict do nothing;

  insert into ontology.concept_edges (ontology_version_id, subject_concept_id, predicate_key, object_concept_id, confidence, provenance_type, provenance, status)
  select new_version_id, e.subject_concept_id, e.predicate_key, e.object_concept_id, e.confidence, e.provenance_type, e.provenance, e.status
    from ontology.concept_edges e where e.ontology_version_id = old_version_id
  on conflict do nothing;

  insert into ontology.motif_rules (id, ontology_version_id, rule_key, evidence_target_concept_id, output_concept_id, evidence_predicate_key, output_predicate_key, rule_kind, minimum_independence_groups, minimum_strength, configuration, status)
  select extensions.gen_random_uuid(), new_version_id, m.rule_key, m.evidence_target_concept_id, m.output_concept_id, m.evidence_predicate_key, m.output_predicate_key, m.rule_kind, m.minimum_independence_groups, m.minimum_strength, m.configuration, m.status
    from ontology.motif_rules m where m.ontology_version_id = old_version_id
  on conflict do nothing;

  insert into ontology.external_concept_links (ontology_version_id, concept_id, external_entity_id, link_type, confidence, status)
  select new_version_id, x.concept_id, x.external_entity_id, x.link_type, x.confidence, x.status
    from ontology.external_concept_links x where x.ontology_version_id = old_version_id
  on conflict do nothing;

  -- 1. The concepts. A key already held is left alone by the conflict clause,
  --    which is how the six merges and `work:hearthstone` land as contributions
  --    to an existing concept rather than as a second one.
  insert into ontology.concepts (id, concept_key)
  select extensions.gen_random_uuid(), i.concept_key from import_concept i
  on conflict (concept_key) do nothing;
  get diagnostics concepts_minted = row_count;

  -- 2. The revisions, at the new version only. The copy-forward above already
  --    carried every existing concept's revision, so `do nothing` is what keeps
  --    `activity:soccer` reading "Soccer" rather than "association football".
  insert into ontology.concept_revisions (
    ontology_version_id, concept_id, preferred_label, concept_kind,
    definition, sensitivity, inference_policy, status, metadata)
  select new_version_id, c.id, i.preferred_label, i.concept_kind, null,
         'ordinary', 'review_required', 'active', i.metadata
    from import_concept i
    join ontology.concepts c on c.concept_key = i.concept_key
  on conflict (ontology_version_id, concept_id) do nothing;
  get diagnostics revisions_added = row_count;

  -- 3. The labels.
  --
  --    **A normalized form already owned by another concept is refused**, not
  --    reassigned — hanging a second name on somebody else's concept is how nine
  --    artists once became one. Counted rather than silently skipped.
  --
  --    **And a `preferred` label is demoted to `alternate` where the concept
  --    already has one.** Only relevant to the six merges and to keys we already
  --    hold; two preferred labels on one concept is not a conflict the unique
  --    index catches, since `label_type` is part of the key.
  insert into ontology.concept_labels (
    ontology_version_id, concept_id, label, normalized_label, locale,
    label_type, provenance_type, confidence, status, external_ref)
  select new_version_id, c.id, i.label, i.normalized_label, i.locale,
         case
           when i.label_type = 'preferred' and exists (
             select 1 from ontology.concept_labels held
              where held.ontology_version_id = new_version_id
                and held.concept_id = c.id
                and held.label_type = 'preferred'
                and held.status = 'active')
           then 'alternate' else i.label_type
         end,
         'external', 1.0, 'active',
         jsonb_build_object(
           'provider', 'wikidata',
           'external_id', i.external_id,
           'canonical_url', 'https://www.wikidata.org/entity/' || i.external_id,
           'license', 'CC0-1.0')
    from import_label i
    join ontology.concepts c on c.concept_key = i.concept_key
   where not exists (
     select 1 from ontology.concept_labels taken
      where taken.ontology_version_id = new_version_id
        and taken.status = 'active'
        and taken.normalized_label = i.normalized_label
        and taken.concept_id <> c.id)
  on conflict (ontology_version_id, concept_id, locale, normalized_label, label_type)
    do nothing;
  get diagnostics labels_added = row_count;

  select count(*) into labels_refused
    from import_label i
    join ontology.concepts c on c.concept_key = i.concept_key
   where exists (
     select 1 from ontology.concept_labels taken
      where taken.ontology_version_id = new_version_id
        and taken.status = 'active'
        and taken.normalized_label = i.normalized_label
        and taken.concept_id <> c.id);

  -- 4. The parent. **A fixed hub for five slices; for athletes the first
  --    candidate the database actually holds.** A concept with no `broader`
  --    edge answers null from `concept_block` and lands under "Other", so a
  --    parent that cannot be resolved is a defect rather than a shrug — and the
  --    assertion below refuses the migration if any minted concept has none.
  --
  --    A concept that already has an active `broader` edge is left alone: the
  --    six merges must not acquire a second parent from a slice that was only
  --    ever a route to their labels.
  insert into ontology.concept_edges (
    ontology_version_id, subject_concept_id, predicate_key, object_concept_id,
    confidence, provenance_type, provenance, status)
  select new_version_id, subject.id, 'broader', object.id, 1.0, 'curated',
         jsonb_build_object('source', '0199_wikidata_slices',
                            'slice', i.metadata->>'slice'),
         'active'
    from import_concept i
    join ontology.concepts subject on subject.concept_key = i.concept_key
    cross join lateral (
      select o.id
        from ontology.concepts o
       where o.concept_key = coalesce(
               i.parent_key,
               (select candidate
                  from unnest(i.parent_candidates) as candidate
                 where exists (
                   select 1 from ontology.concept_revisions pr
                     join ontology.concepts pc on pc.id = pr.concept_id
                    where pc.concept_key = candidate
                      and pr.ontology_version_id = new_version_id
                      and pr.status = 'active')
                 limit 1))
       limit 1
    ) as object
   where not exists (
     select 1 from ontology.concept_edges held
      where held.ontology_version_id = new_version_id
        and held.subject_concept_id = subject.id
        and held.predicate_key = 'broader'
        and held.status = 'active')
  on conflict do nothing;
  get diagnostics edges_added = row_count;

  -- 5. What must hold before this is published.

  -- Nothing new means no version.
  if concepts_minted = 0 then
    raise exception '0199: no concept was minted, which is not the measured state';
  end if;

  -- Every imported concept reaches a hub. Read through `concept_block`, which
  -- is what Memories actually calls, rather than by counting edges.
  select count(*) into unparented
    from import_concept i
    join ontology.concepts c on c.concept_key = i.concept_key
   where semantic_private.concept_block(c.id, new_version_id) is null;
  if unparented > 0 then
    raise exception '0199: % imported concept(s) reach no hub and would land under Other', unparented;
  end if;

  -- No new ambiguity.
  select count(*) into ambiguous_after
    from (select l.normalized_label
            from ontology.concept_labels l
           where l.ontology_version_id = new_version_id and l.status = 'active'
           group by l.normalized_label having count(distinct l.concept_id) > 1) as now_ambiguous;
  if ambiguous_after <> ambiguous_before then
    raise exception '0199: ambiguity went from % to %, so this added %',
      ambiguous_before, ambiguous_after, ambiguous_after - ambiguous_before;
  end if;

  -- The provenance survived the copy-forward. `0179` and `0180` each dropped
  -- this table and nothing raised; a count is what would have caught it.
  select count(*) into links_after
    from ontology.external_concept_links where ontology_version_id = new_version_id;
  if links_after < links_before then
    raise exception '0199: external_concept_links went from % to % in the copy-forward',
      links_before, links_after;
  end if;

  -- **Nothing prohibited was minted.** The tool refused six political and
  -- religious disciplines; this is the same question asked of the result rather
  -- than of the tool, because a check on the producer is not a check on what
  -- was produced.
  select count(*) into prohibited
    from import_concept i
   where i.concept_key ~ '(religion|politic|ethnic|nationality|ancestry|sexual_orientation|health_condition|disability|diagnosis)'
      or i.concept_kind in ('identity');
  if prohibited > 0 then
    raise exception '0199: % imported concept(s) name a prohibited subject', prohibited;
  end if;

  -- And the refused YouTube topics still resolve to nothing. These five must
  -- never become vocabulary, whatever a slice returns.
  select string_agg(probe.term, ', ') into refused_topic
    from (values ('religion'), ('politics'), ('health'), ('military'), ('society')) as probe(term)
   where exists (
     select 1 from ontology.concept_labels l
      where l.ontology_version_id = new_version_id
        and l.status = 'active'
        and l.normalized_label = probe.term);
  if refused_topic is not null then
    raise exception '0199: a refused topic became resolvable: %', refused_topic;
  end if;

  perform ontology.publish_version(new_version_id);

  -- 6. Read back through the vocabulary, not through the inserts. The question
  --    is whether the terms this was written for now resolve and land somewhere
  --    a person would recognise, and only a lookup answers it.
  select semantic_private.concept_block(c.id, new_version_id) into probe_block
    from ontology.concept_labels l
    join ontology.concepts c on c.id = l.concept_id
   where l.ontology_version_id = new_version_id and l.status = 'active'
     and l.normalized_label = 'cubism';
  if probe_block is distinct from 'hub:arts_live' then
    raise exception '0199: cubism blocks to %, expected hub:arts_live', coalesce(probe_block, '(nothing)');
  end if;

  select semantic_private.concept_block(c.id, new_version_id) into probe_block
    from ontology.concept_labels l
    join ontology.concepts c on c.id = l.concept_id
   where l.ontology_version_id = new_version_id and l.status = 'active'
     and l.normalized_label = 'archaeology';
  if probe_block is distinct from 'hub:ideas_learning' then
    raise exception '0199: archaeology blocks to %, expected hub:ideas_learning', coalesce(probe_block, '(nothing)');
  end if;

  select semantic_private.concept_block(c.id, new_version_id) into probe_block
    from ontology.concept_labels l
    join ontology.concepts c on c.id = l.concept_id
   where l.ontology_version_id = new_version_id and l.status = 'active'
     and l.normalized_label = 'league of legends';
  if probe_block is distinct from 'hub:games_play' then
    raise exception '0199: league of legends blocks to %, expected hub:games_play', coalesce(probe_block, '(nothing)');
  end if;

  select semantic_private.concept_block(c.id, new_version_id) into probe_block
    from ontology.concept_labels l
    join ontology.concepts c on c.id = l.concept_id
   where l.ontology_version_id = new_version_id and l.status = 'active'
     and l.normalized_label = 'minecraft';
  if probe_block is distinct from 'hub:games_play' then
    raise exception '0199: minecraft blocks to %, expected hub:games_play', coalesce(probe_block, '(nothing)');
  end if;

  -- The merge, read from the other end: `association football` must now be a
  -- spelling of the concept we already had, not a concept of its own. This is
  -- the only surviving check on the merge list, the athlete that motivated it
  -- having gone with its slice.
  if not exists (
    select 1 from ontology.concept_labels l
      join ontology.concepts c on c.id = l.concept_id
     where l.ontology_version_id = new_version_id and l.status = 'active'
       and l.normalized_label = 'association football'
       and c.concept_key = 'activity:soccer') then
    raise exception '0199: association football did not merge into activity:soccer';
  end if;

  select semantic_private.enqueue_recompute_on_analysis_change(
           'ontology ' || next_version || ': names recovered from article titles'
         ) into enqueued;

  raise notice '0199: % published — % concept(s), % revision(s), % label(s) (% refused on collision), % edge(s), % recompute job(s)',
    next_version, concepts_minted, revisions_added, labels_added, labels_refused, edges_added, enqueued;
end;
$$;

commit;
